import {jest} from '@jest/globals';
import Ajv from 'ajv';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry input validation', () => {
  it('rejects an enum-violating input without calling the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'set_unit',
        description: 'Set the display unit',
        inputSchema: {
          type: 'object',
          properties: {unit: {type: 'string', enum: ['celsius', 'fahrenheit']}},
          required: ['unit'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'ok';
      }
    );

    const response = await registry.execute('set_unit', {unit: 'kelvin'});

    expect({executorCalls, rejected: response.result.includes('unit')}).toEqual({
      executorCalls: 0,
      rejected: true,
    });
  });

  it('throws at register time naming the tool for a static inputSchema that does not compile', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_unit',
          description: 'Has an invalid JSON Schema type',
          inputSchema: {type: 'object', properties: {unit: {type: 'not-a-type'}}},
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_unit/);
  });

  it('compiles a static inputSchema once across ten execute calls', async () => {
    const registry = new ToolRegistry();
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    registry.register(
      {name: 'ping', description: 'Takes no input', inputSchema: {type: 'object', properties: {}}},
      async () => 'pong'
    );

    for (let call = 0; call < 10; call += 1) {
      await registry.execute('ping', {});
    }

    const {calls: compileCalls} = compile.mock;
    const count = compileCalls.length;
    compile.mockRestore();
    expect(count).toBe(1);
  });

  it('compiles a function-valued inputSchema once while the returned schema object is unchanged', async () => {
    const registry = new ToolRegistry();
    const schema = {type: 'object', properties: {}};
    registry.register(
      () => ({name: 'lazy_ping', description: 'Takes no input', inputSchema: schema}),
      async () => 'pong'
    );
    const compile = jest.spyOn(Ajv.prototype, 'compile');

    for (let call = 0; call < 10; call += 1) {
      await registry.execute('lazy_ping', {});
    }

    const {calls: compileCalls} = compile.mock;
    const count = compileCalls.length;
    compile.mockRestore();
    expect(count).toBe(1);
  });
});

